; Actor step of the main loop. Calls wake_idle_enemies, then in the demo reads one byte of the demo stream
; (demo_input_ptr, from demo_input_stream): low nybble = joystick bits of Bruce (actor_joy_dir), high
; nybble = fire (actor_fire). Then for each active actor (X = 2 Ninja, 1 Yamo, 0 Bruce; bit 0 of
; actor_flags) it calls actor_action_step and select_actor_pose. In room 19 the joystick of Bruce is
; forced: up while the room_time high byte is below 2 (512 frames), then no input.
update_actors
        jsr wake_idle_enemies
        lda game_mode
        bne update_actors_start
        ldy #$00
        lda (demo_input_ptr),y
        and #$0f
        sta actor_joy_dir
        lda (demo_input_ptr),y
        lsr
        lsr
        lsr
        lsr
        sta actor_fire
        inc demo_input_ptr
        bne update_actors_start
        inc demo_input_ptr+1
update_actors_start
        ldx #$02
update_actors_loop
        lda actor_flags,x
        and #$01
        beq update_actors_next
        lda room
        cmp #$13                        ; room 19: the congratulations room
        bne update_actors_step
        lda room_time+1
        cmp #$02
        bcs update_actors_no_input
        lda #$0e                        ; joystick up (bit 0 low)
        bne update_actors_store_input
update_actors_no_input
        lda #$0f                        ; no direction
update_actors_store_input
        sta actor_joy_dir
update_actors_step
        jsr actor_action_step
        jsr select_actor_pose
update_actors_next
        dex
        bpl update_actors_loop
        rts
; Print message A (pointer table message_ptrs) on text row X at offset Y from the row start.
; Text row 0 = screen row 0, row 1 = screen row 1, row n >= 2 = screen rows 2n-1 and 2n (text_line_top_lo/hi
; and text_line_bottom_lo/hi, built by build_screen_row_tables). Each message byte b gives character
; c = b - $20: c AND $7F goes to the upper screen row and c OR $80 to the lower row, so text is two rows high.
; Byte $A0 ends the message. When text_single_height is nonzero the lower row goes to io1_dummy (lost), so
; the text is one row high. Rows 0 and 1 are always one row high. Uses row_ptr_top, data_ptr and
; row_ptr_bottom. Changes A, X, Y.
print_message
        pha
        jsr set_text_row_pointers
        pla
        asl
        tax
        sty data_ptr                    ; Y = start offset
        lda message_ptrs,x              ; message pointer - Y, so that (data_ptr),y is the first byte
        sec
        sbc data_ptr
        sta data_ptr
        lda message_ptrs+1,x
        sbc #$00
        sta data_ptr+1
print_message_loop
        lda (data_ptr),y
        sec
        sbc #$20                        ; character = byte - $20
        cmp #$80                        ; byte $A0: end
        beq print_message_done
        and #$7f
        sta (row_ptr_top),y             ; upper half
        ora #$80
        sta (row_ptr_bottom),y          ; lower half
